// Normalise both triggers to { user_id, source }.
//  - Schedule trigger  -> user_id = null  -> batch over all recently-active users.
//  - Webhook -> single user. Callers: Supabase DB webhook on mobile_checkins
//    INSERT (body.record.app_user_id, source 'checkin') or the notes-ingestion
//    workflow (body.app_user_id, trigger 'note').
// A webhook call WITHOUT a resolvable user id is dropped (never fall through to
// a full batch run from a malformed webhook).
const results = [];
for (const item of $input.all()) {
  const j = item.json ?? {};
  const isWebhook = j.body !== undefined || j.headers !== undefined;
  const b = j.body ?? {};
  const rec = b.record ?? b;
  const id = Number(rec.app_user_id ?? rec.user_id ?? NaN);
  const src = ['checkin', 'note'].includes(b.trigger ?? rec.trigger) ? (b.trigger ?? rec.trigger) : 'checkin';
  if (Number.isInteger(id) && id > 0) {
    results.push({ json: { user_id: id, source: src } });
  } else if (!isWebhook) {
    results.push({ json: { user_id: null, source: 'daily' } });
  }
}
return results;

parameters.text:
=You are the recommendation engine for SPARx, IGNTD's recovery app built on Dr. Adi Jaffe's approach: compassionate, shame-free, strengths-based, meeting people exactly where they are.

USER CONTEXT
- Working on: {{ $json.addiction_label }}
- Recent app check-ins, newest first (mood 0-100; 'used' = engaged in the behaviour): {{ JSON.stringify($json.recent_checkins) }}
- Earlier daily assessments (self-statement + emotions): {{ JSON.stringify($json.prod_checkins) }}
- CLINICAL SESSION NOTES from their coach (individual + group sessions) — summaries, themes, concerns, wins, and what content should focus on next. This is your strongest signal; weight it above everything else when present: {{ JSON.stringify($json.session_notes) }}
- Lowest Wheel of Life areas right now (0-10): {{ JSON.stringify($json.lowest_wheel_areas) }}
- Lessons they recently worked through: {{ JSON.stringify($json.recent_lessons) }}

CANDIDATE VIDEOS — the ONLY videos you may recommend:
{{ JSON.stringify($json.candidates) }}

CANDIDATE LESSONS & WORKSHOPS — the ONLY lessons/workshops you may recommend:
{{ JSON.stringify($json.lesson_candidates) }}

TASK
Pick the 3 to 5 best videos, and up to 2 lessons/workshops, that meet this user where they are right now.

Rules:
- Use only snippet_id / lesson_id values that appear in the candidate lists. Never invent an id.
- Anchor picks in the signals, in priority order: (1) session-note focus_areas and concerns; (2) latest check-in mood/struggles — a slip ('used' = yes, amount 'more') gets shame-free relapse content, never punitive; (3) lowest wheel areas; (4) natural next step after recent lessons, not a repeat.
- Prefer variety across the picks.
- If lesson_candidates is empty, return an empty lesson_recommendations array.
- If the signals are sparse, fall back to broadly useful foundational content and say so in the reason.
- reason: ONE warm, specific sentence in Adi's voice explaining why this content, for this user, today. It may be shown to the user.
- CONFIDENTIALITY: never quote, paraphrase, or reveal the existence of coach/session notes in any reason. The notes inform WHAT you pick, never what you SAY. A reason like "because your coach mentioned…" is forbidden; anchor the wording in the user's own check-ins or general growth instead.

parameters.jsCode:
// Hallucination guard + provenance shaping.
// - Drop any id the model invented (must be in this user's candidate pools).
// - Cap videos at 5, lessons/workshops at 2.
// - Build the provenance rows (reason + the exact signal snapshot that drove
//   the pick) and pre-escape everything for safe SQL inlining.
const esc = (s) => String(s ?? '').replace(/'/g, "''");
const results = [];
for (const item of $input.all()) {
  const src = $('Gather user signals + candidates').itemMatching(item.index)?.json ?? {};
  const out = item.json.output ?? item.json;
  const userId = Number(src.user_id);
  if (!Number.isInteger(userId)) continue;

  const videoPool = new Set((src.candidates ?? []).map((c) => Number(c.snippet_id)));
  const lessonPool = new Map((src.lesson_candidates ?? []).map((c) => [Number(c.lesson_id), c.content_type]));

  const videos = (out.video_recommendations ?? [])
    .map((r) => ({ id: Number(r.snippet_id), reason: String(r.reason ?? '').slice(0, 500) }))
    .filter((r) => Number.isInteger(r.id) && videoPool.has(r.id))
    .slice(0, 5);
  const lessons = (out.lesson_recommendations ?? [])
    .map((r) => ({ id: Number(r.lesson_id), reason: String(r.reason ?? '').slice(0, 500) }))
    .filter((r) => Number.isInteger(r.id) && lessonPool.has(r.id))
    .map((r) => ({ ...r, content_type: lessonPool.get(r.id) === 'workshop' ? 'workshop' : 'lesson' }))
    .slice(0, 2);
  if (!videos.length && !lessons.length) continue;

  // Explainability snapshot: the signals (NOT the candidate pools) fed to the model.
  const signals = {
    addiction: src.addiction_label,
    recent_checkins: src.recent_checkins,
    prod_checkins: src.prod_checkins,
    session_note_themes: (src.session_notes ?? []).map((n) => ({
      date: n.date, source: n.source, themes: n.themes, focus_areas: n.focus_areas })),
    lowest_wheel_areas: src.lowest_wheel_areas,
    recent_lessons: src.recent_lessons,
  };

  const ledger = [
    ...videos.map((v) => ({ content_type: 'snippet', content_id: v.id, reason: v.reason })),
    ...lessons.map((l) => ({ content_type: l.content_type, content_id: l.id, reason: l.reason })),
  ];

  results.push({
    json: {
      user_id: userId,
      source: String(src.source ?? 'daily'),
      has_videos: videos.length > 0,
      video_id_list: videos.map((v) => v.id).join(',') || '0',
      ledger_sql: esc(JSON.stringify(ledger)),
      signals_sql: esc(JSON.stringify(signals)),
    },
  });
}
return results;
